def is_scratch_file(rel: str) -> bool:
    return any(p.search(rel) for p in SCRATCH_PATTERNS)


@dataclass

def build_file_tools(workspace: Path, written: dict[str, str]) -> list[BaseTool]:
    @tool
    def write_file(file_path: str, content: str) -> str:
        """Write full content to a file (relative to the repo root). Creates parent directories."""
        try:
            abs_path, rel = resolve_in_workspace(workspace, file_path)
        except PathEscapeError as exc:
            return str(exc)
        # The acceptance test grades this task; letting the coder rewrite it would make
        # the gate measure nothing. Unit tests elsewhere are fine.
        if rel.startswith(ACCEPTANCE_TEST_DIR):
            return (
                f'Refusing to write "{rel}": {ACCEPTANCE_TEST_DIR} holds the acceptance tests this task is '
                "graded against. Put unit tests elsewhere under tests/."
            )
        if is_scratch_file(rel):
            return (
                f'Refusing to write "{rel}": helper/debug scripts get committed with everything else. '
                "Write only the source and test files the task calls for."
            )
        abs_path.parent.mkdir(parents=True, exist_ok=True)
        abs_path.write_text(content)
        written[rel] = content
        return f"Written: {rel}"

@tool
    def read_file(file_path: str) -> str:
        """Read an existing file (relative to the repo root) before modifying it."""
        try:
            abs_path, _ = resolve_in_workspace(workspace, file_path)
            return abs_path.read_text()
        except (PathEscapeError, OSError):
            return f"File not found: {file_path}"

    @tool
    def list_dir(directory: str = ".") -> str:
        """List files in a directory (relative to the repo root)."""
        try:
            abs_path, _ = resolve_in_workspace(workspace, directory) if directory not in ("", ".") else (workspace, ".")
        except PathEscapeError as exc:
            return str(exc)
        if not abs_path.is_dir():
            return f"Not a directory: {directory}"
        skip = {".git", ".venv", "node_modules", "__pycache__"}
        return "\n".join(sorted(p.name + ("/" if p.is_dir() else "") for p in abs_path.iterdir() if p.name not in skip))

    return [write_file, read_file, list_dir]

def system_prompt(ctx: CoderContext) -> str:
    sections = [
        f"You are an expert {ctx.language} developer implementing one task of a larger plan.",
        f"## Specification (read-only)\n**Goal:** {ctx.spec.goal}\n**Technical notes:** {ctx.spec.technical_notes}",
        f"## Your task\n**Title:** {ctx.task.title}\n**Description:** {ctx.task.description}\n"
        f"**Target files:** {', '.join(ctx.task.target_files)}\n**Definition of Done:** {ctx.task.definition_of_done}"
        + (
            f"\n**Interface (binding — implement exactly these names and signatures):**\n{ctx.task.interface}"
            if ctx.task.interface
            else ""
        ),
    ]
    if ctx.test_content:
        sections.append(
            f"## Acceptance test for this task\n```\n{ctx.test_content}\n```\n"
            "It was written against the Definition of Done. Make it pass."
        )
    if ctx.human_hint:
        sections.append(
            "## Guidance from a human (takes priority)\n"
            f"This task ran out of attempts before and a human reviewed it. Their guidance:\n{ctx.human_hint}"
        )
    if ctx.lessons:
        sections.append("## Lessons from past reviews of this repository\n" + "\n".join(f"- {x}" for x in ctx.lessons))
    if ctx.retrieved_context:
        sections.append(f"## Retrieved repository context\n{ctx.retrieved_context}")
    sections.append(
        "## Instructions\n"

async def run_coder(ctx: CoderContext, retriever: HybridRetriever | None, feedback: str | None = None) -> CoderResult:
    s = get_settings()
    written: dict[str, str] = {}
    tools = build_file_tools(ctx.workspace, written)
    if retriever is not None:
        tools += make_search_tools(retriever)

    middleware: list[Any] = [
        ModelCallLimitMiddleware(run_limit=MAX_MODEL_CALLS, exit_behavior="end"),
        ModelRetryMiddleware(max_retries=2),
    ]
    if s.fallback_model and s.fallback_model != s.coder_model:
        middleware.append(ModelFallbackMiddleware(chat_model(s.fallback_model, temperature=0.1)))

agent = create_agent(
        chat_model(s.coder_model, temperature=0.1),
        tools=tools,
        system_prompt=system_prompt(ctx),
        middleware=middleware,
        name="coder",
    )
    user = (
        f"The previous attempt was rejected. Fix these problems and rewrite the affected files:\n\n{feedback}"
        if feedback
        else "Implement the task. Start with the main implementation file."
    )
    try:
        await agent.ainvoke(
            {"messages": [{"role": "user", "content": user}]},
            config={"tags": ["coder", f"task:{ctx.task.id}"], "recursion_limit": MAX_MODEL_CALLS * 3},
        )
    except Exception as exc:  # noqa: BLE001 — an agent crash is a failed attempt, not a dead run
        return CoderResult(task_id=ctx.task.id, success=False, written_files=written, error=str(exc)[:2000])
    if not written:
        return CoderResult(task_id=ctx.task.id, success=False, error="Coder wrote no files")
    return CoderResult(task_id=ctx.task.id, success=True, written_files=written)

def _revision_message(label: str, previous: object, feedback: str) -> HumanMessage:
    return HumanMessage(
        f"## Previous {label} (rejected by reviewer)

```json
{json.dumps(previous, indent=2)}
```

"
        f"## Reviewer feedback

{feedback}

"
        f"Revise the {label} to address this feedback. Keep everything the feedback doesn't ask to change."
    )

async def generate_spec(
    prompt: str, repo_context: str, previous: Spec | None = None, feedback: str | None = None
) -> Spec:
    messages = [
        SystemMessage(SPEC_SYSTEM),
        HumanMessage(
            (f"## Relevant repository context\n\n{repo_context}" if repo_context else "## Repository\n\nEmpty.")
            + f"\n\n## User request\n\n{prompt}"
        ),
    ]
    if previous and feedback:
        messages.append(_revision_message("spec", previous.model_dump(), feedback))
    s = get_settings()
    runnable = structured(s.orchestrator_model, SpecDraft)
    draft: SpecDraft | None = None
    for attempt in range(SPEC_ATTEMPTS):
        try:
            draft = await runnable.ainvoke(
                messages if attempt == 0 else [*messages, LIST_FIELDS_HINT],
                config={"tags": ["orchestrator", "spec"]},
            )
            break
        except Exception as exc:  # noqa: BLE001 — schema violations surface as several exception types
            if attempt == SPEC_ATTEMPTS - 1:
                raise
            log.warning("spec rejected by schema (attempt %s): %s", attempt + 1, str(exc)[:200])
    assert draft is not None
    return Spec(
        id=previous.id if previous else f"spec-{uuid.uuid4().hex[:8]}",
        version=(previous.version + 1) if previous else 1,
        **draft.model_dump(),
    )

async def generate_tasks(
    spec: Spec, repo_context: str, previous: list[Task] | None = None, feedback: str | None = None
) -> list[Task]:
    messages = [
        SystemMessage(TASKS_SYSTEM),
        HumanMessage(
            f"## Approved specification\n\n```json\n{spec.model_dump_json(indent=2)}\n```\n\n"
            + (f"## Repository context\n\n{repo_context}" if repo_context else "")
        ),
    ]
    if previous and feedback:
        messages.append(_revision_message("task list", [t.model_dump() for t in previous], feedback))
    s = get_settings()
    plan: TaskPlan = await structured(s.orchestrator_model, TaskPlan).ainvoke(
        messages, config={"tags": ["orchestrator", "tasks"]}
    )
    return validate_plan([Task(**t.model_dump()) for t in plan.tasks])


REPLAN_SYSTEM = """You are a senior software architect revising a plan after a task failed.

You get the spec, the tasks already completed (their code is committed and must not be redone),
the task that failed with the evidence of why, any human guidance, and the tasks still pending.
Return ONLY the tasks still to do — a replacement for the failed and pending tasks.

def validate_plan(tasks: list[Task]) -> list[Task]:
    """Drop dangling dependencies and break cycles, so the scheduler can never deadlock
    on a plan the model got slightly wrong. Cycles are broken by dropping the in-cycle
    edges of the earliest stuck task in plan order; downstream edges are kept."""
    ids = {t.id for t in tasks}
    for t in tasks:
        t.depends_on = list(dict.fromkeys(d for d in t.depends_on if d in ids and d != t.id))
    done: set[str] = set()
    while len(done) < len(tasks):
        ready = [t for t in tasks if t.id not in done and all(d in done for d in t.depends_on)]
        if ready:
            done.update(t.id for t in ready)
            continue
        stuck = next(t for t in tasks if t.id not in done)
        stuck.depends_on = [d for d in stuck.depends_on if d in done]
    return tasks

def reviewer_chat_model(name: str) -> BaseChatModel:
    """The reviewer must end with a structured ReviewDecision, which the agent obtains by
    forcing a tool call. DeepSeek's thinking mode rejects a forced tool_choice, so it is
    disabled here — for the primary model *and* the fallback. Building the fallback without
    it made every review fail (400) the moment the Opus proxy got rate-limited."""
    return chat_model(name, forces_tool_choice=True)

