class TargetRepo(BaseModel):
    """The repo the workflow clones, codes in, and opens a PR against."""

    owner: str
    repo: str
    base_branch: str = "main"

    @classmethod
    def parse(cls, value: str, base_branch: str = "main") -> TargetRepo:
        owner, _, repo = value.partition("/")
        if not owner or not repo:
            raise ValueError(f'Invalid repo "{value}" — expected owner/repo')
        return cls(owner=owner, repo=repo, base_branch=base_branch)

    @property
    def full_name(self) -> str:
        return f"{self.owner}/{self.repo}"

"""Pluggable auto gate. `detect_gate` picks the strategy from the repo's manifests."""

from __future__ import annotations

from pathlib import Path

from agentflow.gate.base import ACCEPTANCE_TEST_DIR, Gate
from agentflow.gate.python import PythonGate
from agentflow.gate.typescript import TypeScriptGate

__all__ = ["ACCEPTANCE_TEST_DIR", "Gate", "detect_gate", "gate_for"]

_GATES: dict[str, type] = {"python": PythonGate, "typescript": TypeScriptGate}


def gate_for(language: str) -> Gate:
    return _GATES[language]()


def detect_gate(workspace: Path, hint_files: list[str] | None = None) -> Gate:
    """Manifests win; for an empty repo fall back to the extensions the plan targets."""
    if (workspace / "package.json").exists() or (workspace / "tsconfig.json").exists():
        return TypeScriptGate()
    if any((workspace / m).exists() for m in ("pyproject.toml", "requirements.txt", "setup.py")):
        return PythonGate()
    exts = {Path(f).suffix for f in hint_files or []}
    if exts & {".ts", ".tsx"} and not exts & {".py"}:
        return TypeScriptGate()
    return PythonGate()

class CommandResult:
    ok: bool
    code: int
    output: str


async def run_command(
    args: list[str], cwd: Path, timeout: float = 600, env: dict[str, str] | None = None
) -> CommandResult:
    """Run a command, merging stdout+stderr. Test runners and type checkers report
    diagnostics on stdout; reading only stderr once told the coder a task failed
    without saying why."""
    try:
        proc = await asyncio.create_subprocess_exec(
            *args,
            cwd=cwd,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.STDOUT,
            env={**os.environ, **env} if env else None,
        )
    except FileNotFoundError as exc:
        return CommandResult(False, 127, f"{args[0]}: command not found ({exc})")
    try:
        out, _ = await asyncio.wait_for(proc.communicate(), timeout)
    except TimeoutError:
        proc.kill()
        return CommandResult(False, -1, f"{' '.join(args)} timed out after {timeout}s")
    text = _ANSI.sub("", out.decode(errors="replace"))
    return CommandResult(proc.returncode == 0, proc.returncode or 0, text)


def tail(output: str, n: int = 20) -> list[str]:
    return [line for line in output.splitlines() if line.strip()][-n:]


def with_fallback(lines: list[str], raw: str) -> list[str]:
    """Never hand the coder an empty error list: if the filter matched nothing
    (e.g. a runner that failed to start), fall back to the raw tail."""
    return lines or tail(raw)

def summarize(errors: dict[str, list[str]]) -> GateResult:
    errors = {k: v for k, v in errors.items() if v}
    if not errors:
        return GateResult(passed=True)
    summary = "\n\n".join(f"{name} ({len(lines)}):\n" + "\n".join(lines[:5]) for name, lines in errors.items())
    return GateResult(passed=False, errors=errors, summary=summary)

def extract_pytest_failures(raw: str, per_failure: int = 6) -> list[str]:
    """Keep the *reason* each test failed: the FAILED/ERROR marker, the `E ` assertion
    lines, and exception lines. Test titles alone made the coder re-guess the same fix."""
    lines = raw.splitlines()
    keep: set[int] = set()
    for i, line in enumerate(lines):
        if line.startswith(("FAILED", "ERROR")) or line.lstrip().startswith("E "):
            keep.add(i)
        elif re.match(r"^\s*[A-Za-z]*(Error|Exception)\b", line[:2000]):
            keep.update(range(i, min(len(lines), i + per_failure)))
    return [lines[i] for i in sorted(keep) if lines[i].strip()]


def _has_mypy_config(ws: Path) -> bool:
    if (ws / "mypy.ini").exists() or (ws / ".mypy.ini").exists():
        return True
    pyproject = ws / "pyproject.toml"
    return pyproject.exists() and "[tool.mypy]" in pyproject.read_text(errors="ignore")

def extract_vitest_failures(raw: str, per_failure: int = 6, max_line: int = 2000) -> list[str]:
    """Marker lines plus the diagnostics that follow them. Deliberately no alternation
    regex over whole lines: one with `expected .+ to ` backtracked quadratically and
    took seconds on a single 60k-char assertion diff."""
    lines = raw.splitlines()
    keep: set[int] = set()
    for i, line in enumerate(lines):
        if "FAIL" in line or "✗" in line or "×" in line:
            keep.update(range(i, min(len(lines), i + 1 + per_failure)))
        head = line[:max_line]
        if (
            re.match(r"^\s*[A-Za-z]*Error\b", head)
            or "Unhandled error" in head
            or ("expected " in head and " to " in head)
        ):
            keep.add(i)
    return [lines[i] for i in sorted(keep) if lines[i].strip()]


def _has_eslint(ws: Path) -> bool:
    if any((ws / c).exists() for c in ESLINT_CONFIGS):
        return True
    pkg = ws / "package.json"
    return pkg.exists() and '"eslintConfig"' in pkg.read_text(errors="ignore")

tsc, tests, lint = await asyncio.gather(
            run_command(["npx", "tsc", "--noEmit"], workspace),
            run_command(test_args, workspace),
            run_command(["npx", "eslint", *targets, "--max-warnings", "0"], workspace) if lint_on else _done(),
        )
        # TS18003 "No inputs were found": a scaffolding task has no sources yet. That is a
        # project-shape condition, not a defect, and wedged every run's first task.
        if not tsc.ok and "error TS18003" in tsc.output:
            tsc = _OK
        # eslint without the TS parser reports "Parsing error" on every file — unfixable
        # by editing code, and tsc already covers syntax.
        if not lint.ok and re.search(r"Parsing error|Cannot find module '@typescript-eslint", lint.output):
            lint = _OK

        return summarize(
            {
                "Dependency install": [install_error] if install_error else [],
                "TypeScript errors": []
                if tsc.ok
                else with_fallback(
                    [line for line in tsc.output.splitlines() if re.search(r"error TS\d+", line)], tsc.output
                ),
                "Test failures": [] if tests.ok else with_fallback(extract_vitest_failures(tests.output), tests.output),
                "Lint errors": [] if lint.ok else tail(lint.output),
            }
        )


