def await_spec_approval(state: WorkflowState) -> dict:
    spec = state["spec"]
    assert spec
    raw = interrupt({"type": "spec_approval", "spec": spec.model_dump()})
    decision = ApprovalDecision.model_validate(raw)
    if not decision.approved:
        return {"spec_approved": False, "spec_feedback": decision.feedback or "Rejected without comment."}
    return {"spec_approved": True, "spec_feedback": None, "status": "planning"}


async def generate_tasks(state: WorkflowState, runtime: Runtime[Deps]) -> dict:
    spec = state["spec"]
    assert spec
    context = await _repo_context(runtime, state, f"{spec.goal}\n{spec.technical_notes}", budget=5000)
    feedback = state.get("tasks_feedback")
    tasks = await orchestrator.generate_tasks(
        spec, context, previous=state.get("tasks") if feedback else None, feedback=feedback
    )
    progress(runtime, f"planned {len(tasks)} tasks", tasks=[t.id for t in tasks])
    return {"tasks": tasks, "status": "task_review"}


def await_task_approval(state: WorkflowState) -> dict:
    raw = interrupt({"type": "tasks_approval", "tasks": [t.model_dump() for t in state["tasks"]]})
    decision = ApprovalDecision.model_validate(raw)
    if not decision.approved:
        return {"tasks_approved": False, "tasks_feedback": decision.feedback or "Rejected without comment."}
    return {"tasks_approved": True, "tasks_feedback": None, "status": "coding"}


# ─── Task loop ───────────────────────────────────────────────────────────────

update: dict = {
        "failure_decisions": {task_id: decision},
        "escalations": {task_id: count + 1},
    }
    if decision.action == "retry":
        # A fresh budget with the human's guidance; the acceptance test stays (the referee
        # or the hint can still change course), the partial code stays on disk.
        task = task_by_id(state, task_id)
        update |= {
            "tasks": replace_task(
                state["tasks"],
                task_id,
                coder_fix_attempts=0,
                gate_failures=0,
                review_cycles=0,
                reviewer_malfunctions=0,
                status="coding",
            ),
            "stalls": {task_id: Stall()},
            "adjudicated": {task_id: False},
            "review_results": {task_id: ReviewResult(task_id=task_id, approved=False)},
            "hints": {task_id: decision.hint or ""},
        }
        if task.coder_fix_attempts and (result := state.get("task_results", {}).get(task_id)):
            update["task_results"] = {task_id: result.model_copy(update={"error": None})}
    return update

decision = state.get("failure_decisions", {}).get(task_id or "")
    if decision and decision.action == "abort":
        reason = f"Stopped by a human after: {reason}"
        open_tasks = [t for t in tasks if t.status not in ("completed", "failed")]
        failed = {t.id: (reason if t.id == task_id else "Not started — run stopped by a human") for t in open_tasks}
        tasks = [t.model_copy(update={"status": "failed"}) if t.id in failed else t for t in tasks]
        progress(runtime, f"run stopped by a human at {task_id}", task=task_id)
        spec = state.get("spec")
        await telegram.send_message(f"🛑 *Run stopped*\n\n*Feature:* {spec.title if spec else '?'}\n{reason[:1500]}")
        return {"status": "failed", "error": reason, "tasks": tasks, "failed_tasks": failed}

    # Skip only the subtree that needed this task. Aborting the whole run threw away
    # every completed, reviewed task; unrelated work is worth finishing.
    blocked = dependents_of(task_id, tasks) if task_id else []
    failed = {task_id: reason} if task_id else {}
    failed |= {b: f'Skipped — depends on failed task "{task_id}"' for b in blocked}
    casualties = {task_id, *blocked}
    tasks = [t.model_copy(update={"status": "failed"}) if t.id in casualties else t for t in tasks]
    progress(runtime, f"task {task_id} failed: {reason[:300]}", task=task_id, skipped=blocked)

async def notify(state: WorkflowState, runtime: Runtime[Deps]) -> dict:
    spec, pr, failed = state["spec"], state.get("pull_request"), state.get("failed_tasks", {})
    lines = [f"✅ *Workflow completed*\n\n*Feature:* {spec.title if spec else '?'}"]
    if failed:
        lines.append(f"*Incomplete:* {', '.join(failed)}")
    if pr:
        lines.append(f"*Pull request:* {pr.url}")
    try:
        await telegram.send_message("\n".join(lines))
    except Exception as exc:  # noqa: BLE001 — a notification must never fail the run
        log.warning("notification failed: %s", exc)
    return {}

def finalize(state: WorkflowState, runtime: Runtime[Deps]) -> dict:
    ws.cleanup_workspace(_ws(state), runtime.context.config.target_repo)
    return {"status": "completed"}

def after_task_approval(state: WorkflowState) -> str:
    return "select_next_task" if state.get("tasks_approved") else "generate_tasks"


def after_task_selection(state: WorkflowState) -> str:
    """Each task starts with its acceptance test, written before any code."""
    return "generate_task_test" if state.get("current_task_id") else "create_pr"


def after_coder(state: WorkflowState, config: WorkflowConfig) -> str:
    """The test was written before the code, so a successful attempt goes straight to the
    gate; the test stays fixed while the coder works against it."""
    task_id = state["current_task_id"]
    assert task_id
    result = state.get("task_results", {}).get(task_id)
    if result and result.success:
        return "run_review"
    if task_by_id(state, task_id).coder_fix_attempts >= config.max_coder_fix_attempts:
        return "escalate"
    return "run_coder"

def after_escalation(state: WorkflowState) -> str:
    """retry → back to the coder with a fresh budget; replan → rewrite the remaining plan;
    skip / abort → handle_failure (which skips the subtree or stops the run)."""
    decision = state.get("failure_decisions", {}).get(state["current_task_id"] or "")
    action = decision.action if decision else "skip"
    return {"retry": "run_coder", "replan": "replan"}.get(action, "handle_failure")


def after_failure(state: WorkflowState) -> str:
    return END if state.get("status") == "failed" else "select_next_task"


def next_runnable(tasks: list[Task]) -> Task | None:
    done = {t.id for t in tasks if t.status == "completed"}
    return next((t for t in tasks if t.status == "pending" and all(d in done for d in t.depends_on)), None)


def dependents_of(task_id: str, tasks: list[Task]) -> list[str]:
    """Every open task that needs `task_id`, directly or transitively."""
    blocked: set[str] = set()
    grew = True
    while grew:
        grew = False
        for t in tasks:
            if t.id in blocked or t.id == task_id or t.status in ("completed", "failed"):
                continue
            if any(d == task_id or d in blocked for d in t.depends_on):
                blocked.add(t.id)
                grew = True
    return sorted(blocked)

"""Graph state. Per-task maps merge on update so a node returns only the keys it changed."""

