def list_files(root: Path) -> list[str]:
    """Repo-relative paths worth indexing. Uses git when available so .gitignore holds."""
    try:
        out = subprocess.run(
            ["git", "ls-files", "--cached", "--others", "--exclude-standard"],
            cwd=root,
            capture_output=True,
            text=True,
            check=True,
        ).stdout.splitlines()
    except (subprocess.CalledProcessError, FileNotFoundError):
        out = [str(p.relative_to(root)) for p in root.rglob("*") if p.is_file()]
    keep = []
    for rel in out:
        p = Path(rel)
        if any(part in SKIP_DIRS for part in p.parts) or p.name in SKIP_FILES:
            continue
        if p.suffix in LANGUAGE_BY_EXT or p.suffix in TEXT_EXTS:
            keep.append(rel)
    return sorted(keep)

def _splitter(suffix: str) -> RecursiveCharacterTextSplitter:
    lang = LANGUAGE_BY_EXT.get(suffix)
    if lang is not None:
        return RecursiveCharacterTextSplitter.from_language(lang, chunk_size=CHUNK_SIZE, chunk_overlap=CHUNK_OVERLAP)
    return RecursiveCharacterTextSplitter(chunk_size=CHUNK_SIZE, chunk_overlap=CHUNK_OVERLAP)


def chunk_file(path: str, text: str, digest: str) -> list[Chunk]:
    suffix = Path(path).suffix
    kind = "doc" if suffix in DOC_EXTS else "code"
    pieces = _splitter(suffix).split_text(text)
    chunks: list[Chunk] = []
    cursor = 0
    for i, piece in enumerate(pieces):
        # Locate each piece to recover its line range; overlap means it may start
        # before the previous piece ended, so search from a little behind the cursor.
        pos = text.find(piece, max(0, cursor - CHUNK_OVERLAP * 2))
        if pos == -1:
            pos = cursor
        start = text.count("\n", 0, pos) + 1
        end = start + piece.count("\n")
        cursor = pos + len(piece)
        chunks.append(Chunk(path, i, piece, start, end, kind, digest))
    return chunks


def read_and_chunk(root: Path, rel: str) -> tuple[str, list[Chunk]] | None:
    data = (root / rel).read_bytes()
    if len(data) > MAX_FILE_BYTES or b"\x00" in data[:4096]:
        return None
    digest = file_hash(data)
    return digest, chunk_file(rel, data.decode("utf-8", errors="replace"), digest)

class HybridRetriever:
    store: ChunkStore
    embeddings: Embeddings
    repo: str
    candidates: int = 20

    async def search(self, query: str, k: int = 8, kind: str | None = None) -> list[Hit]:
        vector = await self.embeddings.aembed_query(query)
        dense = await self.store.search_vector(self.repo, vector, self.candidates, kind)
        lexical = await self.store.search_text(self.repo, query, self.candidates, kind)
        return rrf_merge([dense, lexical], k)


def count_tokens(text: str) -> int:
    return len(_enc.encode(text, disallowed_special=()))


def pack_context(hits: list[Hit], budget_tokens: int = 6000) -> str:
    """Render hits as fenced snippets, best first, until the budget is spent.
    Adjacent chunks of the same file are merged so the model sees contiguous code."""
    by_path: dict[str, list[Hit]] = defaultdict(list)
    order: list[str] = []
    for h in hits:
        if h.path not in by_path:
            order.append(h.path)
        by_path[h.path].append(h)

    out: list[str] = []
    used = 0
    for path in order:
        for h in sorted(by_path[path], key=lambda x: x.start_line):
            block = f"### {path} (lines {h.start_line}-{h.end_line})\n```\n{h.content}\n```"
            cost = count_tokens(block)
            if used + cost > budget_tokens:
                return "\n\n".join(out)
            out.append(block)
            used += cost
    return "\n\n".join(out)

class PgVectorStore:
    def __init__(self, dsn: str, dim: int = 1024, table: str = "code_chunks"):
        if not table.isidentifier():
            raise ValueError(f"bad table name {table!r}")
        self.dsn = dsn
        self.dim = dim
        self.table = table

    async def _conn(self) -> AsyncConnection[Any]:
        return await AsyncConnection.connect(self.dsn, autocommit=True, row_factory=dict_row)  # type: ignore[arg-type]

async def upsert(self, repo: str, chunks: list[Chunk], vectors: list[list[float]]) -> None:
        if not chunks:
            return
        async with await self._conn() as c, c.cursor() as cur:
            await cur.executemany(
                f"""INSERT INTO {self.table}
                   (repo, path, chunk_index, kind, content, start_line, end_line, file_hash, embedding)
                   VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s::vector)
                   ON CONFLICT (repo, path, chunk_index) DO UPDATE SET
                     kind=EXCLUDED.kind, content=EXCLUDED.content, start_line=EXCLUDED.start_line,
                     end_line=EXCLUDED.end_line, file_hash=EXCLUDED.file_hash, embedding=EXCLUDED.embedding""",
                [
                    (repo, ch.path, ch.index, ch.kind, ch.content, ch.start_line, ch.end_line, ch.file_hash, _vec(v))
                    for ch, v in zip(chunks, vectors, strict=True)
                ],
            )

def _hit(r: Any) -> Hit:
    return Hit(r["path"], r["chunk_index"], r["content"], r["start_line"], r["end_line"], r["kind"], float(r["score"]))


def _stem(token: str) -> str:
    for suffix in ("ing", "ed", "es", "s"):
        if token.endswith(suffix) and len(token) - len(suffix) >= 3:
            return token[: -len(suffix)]
    return token


def _tokens(text: str) -> list[str]:
    """Identifier-aware tokens: split snake_case, camelCase and paths, then stem lightly
    so "passwords hashed" meets `password_hash`."""
    text = re.sub(r"([a-z])([A-Z])", r"\1 \2", text)
    return [_stem(t.lower()) for t in re.findall(r"[A-Za-z0-9]+", text) if len(t) > 1]

class InMemoryStore:
    """Same contract without Postgres — for tests, evals and quick local runs."""

    def __init__(self) -> None:
        self.rows: dict[tuple[str, str, int], tuple[Chunk, list[float]]] = {}

    async def setup(self) -> None:
        return None

    async def file_hashes(self, repo: str) -> dict[str, str]:
        return {ch.path: ch.file_hash for (r, _, _), (ch, _) in self.rows.items() if r == repo}

    async def repos(self) -> list[str]:
        return sorted({r for r, _, _ in self.rows})

    async def delete_paths(self, repo: str, paths: list[str]) -> None:
        drop = set(paths)
        self.rows = {key: v for key, v in self.rows.items() if not (key[0] == repo and key[1] in drop)}

    async def upsert(self, repo: str, chunks: list[Chunk], vectors: list[list[float]]) -> None:
        for ch, v in zip(chunks, vectors, strict=True):
            self.rows[(repo, ch.path, ch.index)] = (ch, v)

    def _scoped(self, repo: str, kind: str | None):
        return [(ch, v) for (r, _, _), (ch, v) in self.rows.items() if r == repo and (kind is None or ch.kind == kind)]

    async def search_vector(self, repo: str, vector: list[float], k: int, kind: str | None) -> list[Hit]:
        def cos(a: list[float], b: list[float]) -> float:
            na, nb = math.sqrt(sum(x * x for x in a)), math.sqrt(sum(x * x for x in b))
            return sum(x * y for x, y in zip(a, b, strict=True)) / (na * nb or 1)

